{{
  config(
    materialized='incremental',
    alias='FILE_GENERATED_DETAILS_DIM',
    schema='',
    pre_hook="",
    post_hook="",
    incremental_strategy='merge',
    unique_key=['ID'],
    merge_update_columns=['BATCH_ID','FILE_NAME','APPLICATION_REPORT_ID','VERSION_NO','COMMENTS']
  )
}}
With SQ_SC_RR_BNK_LIABILITY_COVER_FACTOut as (
	/* SubQuery from Source ==>SQ_SQ_SC_RR_BNK_LIABILITY_COVER_FACT */
/* transType: "Source" */
Select 
ID,
MNEMONIC,
SUB_ACCOUNT,
EXCHANGE,
EXCHANGE_ID,
ASSET_CURRENCY_ID,
ASSET_AMOUNT,
ENTITY_ID
 from 
(SELECT
    BNKLIAB.ID,
    BNKLIAB.MNEMONIC,
    BNKLIAB.SUB_ACCOUNT,
    EXCHN.EXCHANGE_MNEMONIC as EXCHANGE,
    BNKLIAB.EXCHANGE_ID as EXCHANGE_ID,
    BNKLIAB.ASSET_CURRENCY_ID,
    BNKLIAB.ASSET_AMOUNT,
    BNKLIAB.ENTITY_ID
 FROM
    RR_BNK_LIABILITY_COVER_FACT as BNKLIAB
 JOIN
  BATCH_MASTER as BM
 ON
  BNKLIAB.BATCH_ID= BM.BATCH_ID
 JOIN
  DW_MART.EXCHANGE_DIM as EXCHN
 ON
  BNKLIAB.EXCHANGE_ID= EXCHN.ID
 JOIN
  DW_MART.VW_ML_CALYP_SUB_ACCOUNT as SACT
 ON
  BNKLIAB.SUB_ACCOUNT= SACT.SUB_ACCOUNT
 WHERE  
  BM.BATCH_FEED_INFO LIKE '%BNK%' AND 
  BM.BATCH_STATUS= 'C' AND 
  BM.BATCH_BUSINESS_FROM_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  ( SYSDATE BETWEEN EXCHN.EFFECTIVE_DATE AND NVL ( EXCHN.EXPIRATION_DATE,TO_DATE ( '31-DEC-2099','DD-MON-YYYY') ) ) AND 
  EXCHN.ENTITY= 'LTD' AND 
   BNKLIAB.BUSINESS_DATE_ID =
 (SELECT
 distinct
    (ID)
 FROM
{{ source('DW_MART', 'CALENDAR_DIM') }}
 WHERE  
  CAL_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  TYPE= 'LTD_STD') AND 
   BNKLIAB.MNEMONIC NOT IN
 (SELECT
    STRING_VALUE
 FROM
    APPLICATION_VARIABLES
 WHERE 
  VARIABLE_NAME IN('BOE_INTEROP_MNEMONIC','BOE_DMO_MNEMONIC')) AND 
  BNKLIAB.ASSET_AMOUNT > 0 AND 
  BNKLIAB.SUB_ACCOUNT  !=  'Q' AND 
  BNKLIAB.ERROR_INDICATOR  != (DECODE((SELECT STRING_VALUE3 FROM
{{ source('DW_MART', 'APPLICATION_VARIABLES') }} WHERE VARIABLE_NAME= 'BOE_STATIC_BNKLIAB_ERROR_IND_VAL' AND ACTIVE_Y_N = 'Y'),'ALL','A','Y')) AND 
  BNKLIAB.SUB_ACCOUNT IN('F','R') AND 
  SACT.IN_DEFAULT_WATERFALL= 'TRUE' AND 
   EXCHN.EXCHANGE_MNEMONIC NOT IN
 (SELECT
    STRING_VALUE3
 FROM
    APPLICATION_VARIABLES
 WHERE  
  VARIABLE_NAME= 'BOE_STATIC_EXCHANGE_VAL' AND 
  ACTIVE_Y_N= 'Y') AND EXISTS 
 (SELECT
 distinct
    MRG_MNEMONIC
 FROM
{{ source('GRR', 'VW_RDR_MEMBER_DTLS') }}
 WHERE  
  VW_RDR_MEMBER_DTLS.MRG_MNEMONIC= BNKLIAB.MNEMONIC AND 
   VW_RDR_MEMBER_DTLS.SERVICE IN
 (SELECT
    A.EXCHANGE_MNEMONIC
 FROM
    EXCHANGE_DIM as A
 WHERE  
  GO_LIVE_DATE <= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  A.DEFAULT_FUND= EXCHN.DEFAULT_FUND)))
 ),

BATCH_MASTEROut as (
	/* transType: "LookupSource" */
Select BATCH_ID, 
		BATCH_FEED_INFO, 
		REMARKS, 
		AUTO_REPORT_SUBMISSION_FLG, 
		BATCH_ID1
 from 
{{ source ('LKP_BATCH_MASTER_1','BATCH_MASTER') }}
 ),

FILE_GENERATED_DETAILS_DIMOut as (
	/* transType: "LookupSource" */
Select BATCH_ID, 
		APPLICATION_REPORT_ID, 
		VERSION_NO, 
		in_BATCH_ID, 
		in_APPLICATION_REPORT_ID
 from 
{{ source ('SC_LKP_FILE_GENERATED_DETAILS_DIM_VERSION_1','FILE_GENERATED_DETAILS_DIM') }}
 ),

SQ_SC_RR_BNK_DSRO_SEC_BALANCES_FACTOut as (
	/* SubQuery from Source ==>SQ_SQ_SC_RR_BNK_DSRO_SEC_BALANCES_FACT */
/* transType: "Source" */
Select 
ID,
BUSINESS_DATE,
MNEMONIC,
SUB_ACCOUNT,
SECURITY_CURRENCY_ID,
SECURITY_PRODUCT_CODE,
MARKET_VALUE,
ENTITY_ID,
MARKET_VALUE_POST_HAIRCUT,
HAIRCUT,
SECURITY_TYPE,
BOE_SECURITY_TYPE
 from 
(SELECT
    DSB.ID,
    DSB.BUSINESS_DATE,
    DSB.MNEMONIC,
    DSB.SUB_ACCOUNT,
    DSB.SECURITY_CURRENCY_ID,
    DSB.SECURITY_PRODUCT_CODE,
    DSB.MARKET_VALUE,
    DSB.ENTITY_ID,
    DSB.MARKET_VALUE_POST_HAIRCUT,
    DSB.HAIRCUT,
    DSB.SECURITY_TYPE,
    DSB.BOE_SECURITY_TYPE
 FROM
    RR_BNK_DSRO_SEC_BALANCES_FACT as DSB
 INNER JOIN 
  BATCH_MASTER as BM
 ON
  DSB.BATCH_ID= BM.BATCH_ID
 WHERE  
  BM.BATCH_FEED_INFO LIKE '%BNK%' AND 
  BM.BATCH_STATUS= 'C' AND 
  BM.BATCH_BUSINESS_FROM_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  DSB.MARKET_VALUE > 0 AND 
  DSB.SUB_ACCOUNT  !=  'Q' AND 
  (NVL(UPPER(DSB.SECURITY_TYPE),'NA') NOT IN('TRIPARTY COLLATERAL') OR DSB.BUSINESS_DATE <(SELECT TO_DATE(STRING_VALUE,'YYYYMMDD') FROM APPLICATION_VARIABLES WHERE VARIABLE_NAME= 'BOE_COLTRL_RPT_MBR_GOLIVE_DATE' AND ACTIVE_Y_N = 'Y')) AND 
  DSB.ERROR_INDICATOR  != (DECODE((SELECT STRING_VALUE3 FROM
{{ source('DW_MART', 'APPLICATION_VARIABLES') }} WHERE VARIABLE_NAME= 'BOE_STATIC_DSRO_ERROR_IND_VAL' AND ACTIVE_Y_N = 'Y'),'ALL','A','Y'))
 UNION ALL 
 SELECT
    TRI.ID,
    TRI.BUSINESS_DATE,
    TRI.MNEMONIC,
    TRI.SUB_ACCOUNT,
    TRI.CURRENCY_ID,
    NULL as SECURITY_PRODUCT_CODE,
    TRI.PRE_HC_MV_COLL_CCY_AMT as MARKET_VALUE,
    TRI.ENTITY_ID,
    TRI.POST_HC_MV_COLL_CCY_AMT as MARKET_VALUE_POST_HAIRCUT,
    TRI.HAIRCUT,
    'Triparty Collateral' as SECURITY_TYPE,
    NULL as BOE_SECURITY_TYPE
 FROM
    RR_BNK_TRIPTYALC_INVST_FACT as TRI
 INNER JOIN 
  BATCH_MASTER as BM
 ON
  TRI.BATCH_ID= BM.BATCH_ID
 WHERE  
  BM.BATCH_FEED_INFO LIKE '%BNK%' AND 
  BM.BATCH_STATUS= 'C' AND 
  BM.BATCH_BUSINESS_FROM_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  ( TRI.MNEMONIC IS NOT NULL AND TRI.BUSINESS_DATE >= ( SELECT TO_DATE ( STRING_VALUE,'YYYYMMDD') FROM APPLICATION_VARIABLES WHERE VARIABLE_NAME = 'BOE_COLTRL_RPT_MBR_GOLIVE_DATE' AND ACTIVE_Y_N = 'Y' ) ) AND 
  TRI.PRE_HC_MV_COLL_CCY_AMT > 0 AND 
  TRI.ERROR_INDICATOR  != (DECODE((SELECT STRING_VALUE3 FROM
{{ source('DW_MART', 'APPLICATION_VARIABLES') }} WHERE VARIABLE_NAME= 'BOE_STATIC_DSRO_ERROR_IND_VAL' AND ACTIVE_Y_N = 'Y'),'ALL','A','Y')) AND 
   TRI.ENTITY_ID IN
 (SELECT
    ID
 FROM
{{ source('DW_MART', 'ENTITY_DIM') }}
 WHERE 
  NAME= 'LCH.LTD'))
 ),

SQ_SC_RR_BNK_CASH_COLLATERAL_FACTOut as (
	/* SubQuery from Source ==>SQ_SQ_SC_RR_BNK_CASH_COLLATERAL_FACT */
/* transType: "Source" */
Select 
ID,
MNEMONIC,
SUB_ACCOUNT,
EXCHANGE_ID,
EXCHANGE,
CASH_COLLATERAL_CURRENCY_ID,
CASH_COLLATERAL_AMOUNT,
ENTITY_ID,
CASH_COLLATERAL_POST_HAIRCUT
 from 
(SELECT
    A.ID,
    A.MNEMONIC,
    A.SUB_ACCOUNT,
    A.EXCHANGE_ID,
    A.EXCHANGE,
    A.CASH_COLLATERAL_CURRENCY_ID,
    A.CASH_COLLATERAL_AMOUNT,
    A.ENTITY_ID,
    A.CASH_COLLATERAL_POST_HAIRCUT
 FROM
 (SELECT
    CASH.ID,
    CASH.MNEMONIC,
    CASH.SUB_ACCOUNT,
    CASH.EXCHANGE_ID,
    CASH.EXCHANGE,
    CASH.CASH_COLLATERAL_CURRENCY_ID,
    CASH.CASH_COLLATERAL_AMOUNT,
    CASH.ENTITY_ID,
    CASH.CASH_COLLATERAL_POST_HAIRCUT,
    VW_PRIM_EXCH_SHAREDMNEMONIC.PRIMARY_EXCHANGE
 FROM
    RR_BNK_CASH_COLLATERAL_FACT as CASH
 JOIN
  BATCH_MASTER as BM
 ON
  CASH.BATCH_ID= BM.BATCH_ID
 JOIN
  DW_MART.EXCHANGE_DIM as EXCHN
 ON
  CASH.EXCHANGE_ID= EXCHN.ID
 LEFT OUTER JOIN 
  DW_MART.VW_PRIM_EXCH_SHAREDMNEMONIC
 ON
  CASH.MNEMONIC= VW_PRIM_EXCH_SHAREDMNEMONIC.MNEMONIC
 WHERE  
  BM.BATCH_FEED_INFO LIKE '%BNK%' AND 
  BM.BATCH_STATUS= 'C' AND 
  BM.BATCH_BUSINESS_FROM_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  ( SYSDATE BETWEEN EXCHN.EFFECTIVE_DATE AND NVL ( EXCHN.EXPIRATION_DATE,TO_DATE ( '31-DEC-2099','DD-MON-YYYY') ) ) AND 
  EXCHN.ENTITY= 'LTD' AND 
   CASH.BUSINESS_DATE_ID =
 (SELECT
 distinct
    (ID)
 FROM
{{ source('DW_MART', 'CALENDAR_DIM') }}
 WHERE  
  CAL_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  TYPE= 'LTD_STD') AND 
  CASH.CASH_COLLATERAL_AMOUNT > 0 AND 
  CASH.SUB_ACCOUNT NOT IN('R','Q') AND 
  CASH.ERROR_INDICATOR  != (DECODE((SELECT STRING_VALUE3 FROM
{{ source('DW_MART', 'APPLICATION_VARIABLES') }} WHERE VARIABLE_NAME= 'BOE_STATIC_CASH_ERROR_IND_VAL' AND ACTIVE_Y_N = 'Y'),'ALL','A','Y')) AND 
   CASH.MNEMONIC NOT IN
 (SELECT
    STRING_VALUE
 FROM
    APPLICATION_VARIABLES
 WHERE 
  VARIABLE_NAME IN('BOE_INTEROP_MNEMONIC','BOE_DMO_MNEMONIC')) AND 
   CASH.EXCHANGE NOT IN
 (SELECT
    STRING_VALUE3
 FROM
    APPLICATION_VARIABLES
 WHERE  
  VARIABLE_NAME= 'BOE_STATIC_EXCHANGE_VAL' AND 
  ACTIVE_Y_N= 'Y')) A
 WHERE  
  (A.PRIMARY_EXCHANGE IS NULL OR A.PRIMARY_EXCHANGE= A.EXCHANGE) AND EXISTS 
 (SELECT
 distinct
    MRG_MNEMONIC
 FROM
{{ source('GRR', 'VW_RDR_MEMBER_DTLS') }}
 WHERE 
  VW_RDR_MEMBER_DTLS.MRG_MNEMONIC= A.MNEMONIC))
 ),

EXP_PASS_THROUGHOut as (
	/* transType: "Expression" */
Select 
	ID as ID,
	 BUSINESS_DATE as BUSINESS_DATE,
	 MNEMONIC as MNEMONIC,
	 SUB_ACCOUNT as SUB_ACCOUNT,
	 SECURITY_CURRENCY_ID as SECURITY_CURRENCY_ID,
	 SECURITY_PRODUCT_CODE as SECURITY_PRODUCT_CODE,
	 MARKET_VALUE as MARKET_VALUE,
	 ENTITY_ID as ENTITY_ID,
	 MARKET_VALUE_POST_HAIRCUT as MARKET_VALUE_POST_HAIRCUT,
	 HAIRCUT as HAIRCUT,
	 SECURITY_TYPE as SECURITY_TYPE,
	 dsf_1.PRIMARY_EXCHANGE as v_EXCHANGE_1,
	 ( CASE WHEN v_EXCHANGE_1 IS NULL THEN dsf_2.SERVICE ELSE v_EXCHANGE_1 END ) as v_EXCHANGE_2,
	 dsf_3.ID as v_EXCHANGE_ID,
	 DECODE ( v_EXCHANGE_2,
	 'TQD',
	 'ED2',
	 v_EXCHANGE_2 ) as o_EXCHANGE,
	 v_EXCHANGE_ID as o_EXCHANGE_ID,
	 ( CASE WHEN v_EXCHANGE_ID IS NOT NULL THEN 'Y' ELSE 'N' END ) as o_VALID_EXCHANGE,
	 'BOE_DSRO_SECURITY_TYPE' as BOE_SECURITY_TYPE_NAME,
	 dsf_4.STRING_VALUE3 as o_BOE_SECURITY_TYPE
From SQ_SC_RR_BNK_DSRO_SEC_BALANCES_FACTOut as SQ_SC_RR_BNK_DSRO_SEC_BALANCES_FACTOut
LEFT JOIN (
SELECT PRIMARY_EXCHANGE, MNEMONIC FROM (  SELECT PRIMARY_EXCHANGE, MNEMONIC,  ROW_NUMBER() OVER (PARTITION BY MNEMONIC ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT PRIMARY_EXCHANGE, MNEMONIC,  ROW_NUMBER() OVER (PARTITION BY MNEMONIC ORDER BY MNEMONIC NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    VW_PRIM_EXCH_SHAREDMNEMONIC )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.MNEMONIC = MNEMONIC
LEFT JOIN (
SELECT SERVICE, MRG_MNEMONIC FROM (  SELECT SERVICE, MRG_MNEMONIC,  ROW_NUMBER() OVER (PARTITION BY MRG_MNEMONIC ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT SERVICE, MRG_MNEMONIC,  ROW_NUMBER() OVER (PARTITION BY MRG_MNEMONIC ORDER BY MRG_MNEMONIC NULLS LAST) AS rnk_fst   FROM ( SELECT    VW_RDR_MEMBER_DTLS.SERVICE as SERVICE,    VW_RDR_MEMBER_DTLS.MEM_EXCHANGE_ID as MEM_EXCHANGE_ID,    VW_RDR_MEMBER_DTLS.MEM_MNEMONIC as MEM_MNEMONIC,    VW_RDR_MEMBER_DTLS.GO_LIVE_DATE as GO_LIVE_DATE,    VW_RDR_MEMBER_DTLS.RESIGNATION_DATE as RESIGNATION_DATE,    VW_RDR_MEMBER_DTLS.MEM_LEI as MEM_LEI,    VW_RDR_MEMBER_DTLS.MEM_NAME as MEM_NAME,    VW_RDR_MEMBER_DTLS.CLEARING_CATEGORY_ID as CLEARING_CATEGORY_ID,    VW_RDR_MEMBER_DTLS.ULTIMATE_PARENT_ID as ULTIMATE_PARENT_ID,    VW_RDR_MEMBER_DTLS.INTERNAL_CREDIT_SCORE as INTERNAL_CREDIT_SCORE,    VW_RDR_MEMBER_DTLS.SM_AGENT_MNEMONIC as SM_AGENT_MNEMONIC,    VW_RDR_MEMBER_DTLS.SM_AGENT_NAME as SM_AGENT_NAME,    VW_RDR_MEMBER_DTLS.SM_AGENT_LEI as SM_AGENT_LEI,    VW_RDR_MEMBER_DTLS.REC as REC,    VW_RDR_MEMBER_DTLS.SUB_ACCOUNT as SUB_ACCOUNT,    VW_RDR_MEMBER_DTLS.HOUSE_CLIENT_FLAG as HOUSE_CLIENT_FLAG,    VW_RDR_MEMBER_DTLS.CLIENT_ACCOUNT_TYPE as CLIENT_ACCOUNT_TYPE,    VW_RDR_MEMBER_DTLS.MRG_MNEMONIC as MRG_MNEMONIC FROM    VW_RDR_MEMBER_DTLS ORDER BY    VW_RDR_MEMBER_DTLS.MRG_MNEMONIC,    NVL ( VW_RDR_MEMBER_DTLS.RESIGNATION_DATE,TO_DATE ( '31-DEC-2099','DD-MON-YYYY' ) ) - - )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.MRG_MNEMONIC = MNEMONIC
LEFT JOIN (
SELECT ID, EXCHANGE_MNEMONIC, EFFECTIVE_DATE, EXPIRATION_DATE FROM (  SELECT ID, EXCHANGE_MNEMONIC, EFFECTIVE_DATE, EXPIRATION_DATE,  ROW_NUMBER() OVER (PARTITION BY EXCHANGE_MNEMONIC, EFFECTIVE_DATE, EXPIRATION_DATE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT ID, EXCHANGE_MNEMONIC, EFFECTIVE_DATE, EXPIRATION_DATE,  ROW_NUMBER() OVER (PARTITION BY EXCHANGE_MNEMONIC, EFFECTIVE_DATE, EXPIRATION_DATE ORDER BY EXCHANGE_MNEMONIC, EFFECTIVE_DATE, EXPIRATION_DATE NULLS LAST) AS rnk_fst   FROM ( SELECT    EXCHANGE_DIM.ID as ID,    EXCHANGE_DIM.EXCHANGE_MNEMONIC as EXCHANGE_MNEMONIC,    EXCHANGE_DIM.EFFECTIVE_DATE as EFFECTIVE_DATE,    NVL(EXCHANGE_DIM.EXPIRATION_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) as EXPIRATION_DATE FROM    EXCHANGE_DIM )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.EXCHANGE_MNEMONIC = v_EXCHANGE_2 AND dsf_3.EFFECTIVE_DATE <= BUSINESS_DATE AND dsf_3.EXPIRATION_DATE >= BUSINESS_DATE
LEFT JOIN (
SELECT STRING_VALUE3, VARIABLE_NAME, STRING_VALUE, STRING_VALUE2 FROM (  SELECT STRING_VALUE3, VARIABLE_NAME, STRING_VALUE, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE, STRING_VALUE2 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE3, VARIABLE_NAME, STRING_VALUE, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE, STRING_VALUE2 ORDER BY VARIABLE_NAME, STRING_VALUE, STRING_VALUE2 NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_4
ON dsf_4.VARIABLE_NAME = 'BOE_VALIDATION_VALUE' AND dsf_4.STRING_VALUE = 'BOE_DSRO_SECURITY_TYPE' AND dsf_4.STRING_VALUE2 = BOE_SECURITY_TYPE
),

EXMP_BNK_LIAB_COLOut1 as (
	/* transType: "Expression" */
Select 
	ID as ID,
	 MNEMONIC as MNEMONIC,
	 SUB_ACCOUNT as SUB_ACCOUNT,
	 EXCHANGE as EXCHANGE,
	 EXCHANGE_ID as EXCHANGE_ID,
	 ASSET_CURRENCY_ID as ASSET_CURRENCY_ID,
	 ASSET_AMOUNT as ASSET_AMOUNT,
	 ENTITY_ID as ENTITY_ID,
	 dsf_1.DF_NAME as v_WATERFALL_LKP,
	 SUBSTRING ( v_WATERFALL_LKP,
	 1,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) -1 ) as v_WATERFALL_NM,
	 v_WATERFALL_NM as o_WATERFALL_NM,
	 SUBSTRING ( v_WATERFALL_LKP,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) + 1 ) as v_WATERFALL_SRVC,
	 v_WATERFALL_SRVC as o_WATERFALL_SRVC,
	 MNEMONIC || '_' || SUB_ACCOUNT as BLC_CollateralAccountID,
	 'Cash' as v_Asset_Type,
	 v_Asset_Type as Asset_Type,
	 dsf_2.CURRENCY_MNEMONIC as v_Ccy,
	 v_Ccy as o_Ccy,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN ASSET_AMOUNT ELSE NULL END ) as Cash_Value,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN v_Ccy ELSE null END ) as Cash_Value_Ccy,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN ASSET_AMOUNT ELSE NULL END ) as ValuePostHaircut,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN v_Ccy ELSE null END ) as ValuePostHaircut_ccy,
	 ( CASE WHEN IN ( SUB_ACCOUNT,
	 'F',
	 'R' ) THEN 'DFLT' ELSE 'MGIN' END ) as CollateralRequirement,
	 SUBSTRING ( TO_DATE ( TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ),
	 'YYYY-MM-DD' ),
	 'YYYY-MM-DD' ),
	 1,
	 10 ) || 'T' || SUBSTRING ( TO_TIMESTAMP ( TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ),
	 'HH24MISS' ),
	 'HH24MISS' ),
	 12 ) as v_Date,
	 TO_VARCHAR ( TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ),
	 'YYYY-MM-DD' ) as v_AS_OF_DATE,
	 :LKP.SC_LKP_APPLICATION_VARIABLES_BOE ( PMSessionName,
	 'BOE_STATIC_VAL' ) as v_APP_REP_ID,
	 :LKP.SC_LKP_FILE_GENERATED_DETAILS_DIM_VERSION ( '{{ var("BATCH_ID") }}',
	 v_APP_REP_ID ) as v_Version,
	 ( CASE WHEN v_Version IS NULL THEN 1 ELSE ( TO_NUMBER ( v_Version ) + 1 ) END ) as v_initial_value_handle,
	 '{{ var("CCP_CODE") }}' || '_' || v_AS_OF_DATE || '_' || 'CCPCollRpt_' || v_Date || '_V' || v_initial_value_handle || '.XML' as v_FILENAME,
	 v_FILENAME as FILENAME,
	 1 as ENABLE_IND,
	 dsf_5.ID as FILE_GEN_DETAILS_ID
From SQ_SC_RR_BNK_LIABILITY_COVER_FACTOut as SQ_SC_RR_BNK_LIABILITY_COVER_FACTOut
LEFT JOIN (
SELECT DF_NAME, ID FROM (   SELECT DF_NAME, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT DF_NAME, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY ID NULLS LAST) AS rnk_fst     FROM ( SELECT        EXCHANGE_DIM.ID as ID,        EXCHANGE_DIM.DEFAULT_FUND || '~' || EXCHANGE_DIM.NAME as DF_NAME  FROM        EXCHANGE_DIM  WHERE       TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') >= EFFECTIVE_DATE AND      TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') <= NVL(EXPIRATION_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.ID = EXCHANGE_ID
LEFT JOIN (
SELECT CURRENCY_MNEMONIC, ID FROM (   SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY ID NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        CURRENCY_DIM )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.ID = ASSET_CURRENCY_ID
LEFT JOIN (
SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME FROM (   SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY STRING_VALUE, VARIABLE_NAME NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        APPLICATION_VARIABLES )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.STRING_VALUE = '{{ var("PMSessionName") }}' AND dsf_3.VARIABLE_NAME = 'BOE_STATIC_VAL'
LEFT JOIN (
