	 ASSET_CURRENCY_ID as ASSET_CURRENCY_ID,
	 ASSET_AMOUNT as ASSET_AMOUNT,
	 ENTITY_ID as ENTITY_ID,
	 dsf_1.DF_NAME as v_WATERFALL_LKP,
	 SUBSTRING ( v_WATERFALL_LKP,
	 1,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) -1 ) as v_WATERFALL_NM,
	 v_WATERFALL_NM as o_WATERFALL_NM,
	 SUBSTRING ( v_WATERFALL_LKP,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) + 1 ) as v_WATERFALL_SRVC,
	 v_WATERFALL_SRVC as o_WATERFALL_SRVC,
	 MNEMONIC || '_' || SUB_ACCOUNT as BLC_CollateralAccountID,
	 'Cash' as v_Asset_Type,
	 v_Asset_Type as Asset_Type,
	 dsf_2.CURRENCY_MNEMONIC as v_Ccy,
	 v_Ccy as o_Ccy,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN ASSET_AMOUNT ELSE NULL END ) as Cash_Value,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN v_Ccy ELSE null END ) as Cash_Value_Ccy,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN ASSET_AMOUNT ELSE NULL END ) as ValuePostHaircut,
	 ( CASE WHEN v_Asset_Type = 'Cash' THEN v_Ccy ELSE null END ) as ValuePostHaircut_ccy,
	 ( CASE WHEN IN ( SUB_ACCOUNT,
	 'F',
	 'R' ) THEN 'DFLT' ELSE 'MGIN' END ) as CollateralRequirement,
	 SUBSTRING ( TO_DATE ( TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ),
	 'YYYY-MM-DD' ),
	 'YYYY-MM-DD' ),
	 1,
