LEFT JOIN (
SELECT STRING_VALUE2, STRING_VALUE FROM (   SELECT STRING_VALUE2, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT STRING_VALUE2, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst     FROM ( SELECT        APPLICATION_VARIABLES.STRING_VALUE2 as STRING_VALUE2,        APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE  FROM        APPLICATION_VARIABLES  WHERE     VARIABLE_NAME= 'BOE_STATIC_VAL' )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
