) dsf_8
ON dsf_8.STRING_VALUE = '{{ var("PMSessionName") }}' AND dsf_8.VARIABLE_NAME = 'BOE_STATIC_VAL'
LEFT JOIN (
SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID FROM (   SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY BATCH_ID, APPLICATION_REPORT_ID NULLS LAST) AS rnk_fst     FROM ( SELECT        MAX(NVL(FILE_GENERATED_DETAILS_DIM.VERSION_NO,0)) as VERSION_NO,        FILE_GENERATED_DETAILS_DIM.BATCH_ID as BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID  FROM        FILE_GENERATED_DETAILS_DIM  INNER JOIN      BATCH_MASTER   ON    FILE_GENERATED_DETAILS_DIM.BATCH_ID= BATCH_MASTER.BATCH_ID AND     FILE_GENERATED_DETAILS_DIM.STATUS= 'C' AND     FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID= '{{ var("REPORT_ID") }}' AND     FILE_GENERATED_DETAILS_DIM.BATCH_ID= '{{ var("BATCH_ID") }}'  GROUP BY        FILE_GENERATED_DETAILS_DIM.BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
