LEFT JOIN (
SELECT ID, BATCH_ID, APPLICATION_REPORT_ID FROM (   SELECT ID, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT ID, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY BATCH_ID, APPLICATION_REPORT_ID NULLS LAST) AS rnk_fst     FROM ( SELECT        FILE_GENERATED_DETAILS_DIM.ID as ID,        FILE_GENERATED_DETAILS_DIM.BATCH_ID as BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID  FROM        FILE_GENERATED_DETAILS_DIM  INNER JOIN      BATCH_MASTER   ON    FILE_GENERATED_DETAILS_DIM.BATCH_ID= BATCH_MASTER.BATCH_ID AND     FILE_GENERATED_DETAILS_DIM.BATCH_ID= '{{ var("BATCH_ID") }}' AND     FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID= '{{ var("REPORT_ID") }}' AND     DATE_TRUNC('DAY',FILE_GENERATED_DETAILS_DIM.FILE_GEN_START_DATETIME)= DATE_TRUNC('DAY',TO_DATE('{{ var("BATCH_START_DATE") }}','DD-MON-YYYY'))  ORDER BY        TRUNC ( FILE_GEN_START_DATETIME ) DESC )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_10
ON dsf_10.BATCH_ID = '{{ var("BATCH_ID") }}' AND dsf_10.APPLICATION_REPORT_ID = '{{ var("REPORT_ID") }}'
