SELECT ACTIVE_Y_N, STRING_VALUE FROM (   SELECT ACTIVE_Y_N, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT ACTIVE_Y_N, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        APPLICATION_VARIABLES )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
