EXP_CASH_COLOut3 as (
	/* transType: "Expression" */
Select 
	ID_CASH as ID_CASH,
	 CC_MNEMONIC as CC_MNEMONIC,
	 CC_CASH_COLLATERAL_CURRENCY_ID as CC_CASH_COLLATERAL_CURRENCY_ID,
	 CC_SUB_ACCOUNT as O_CC_SUB_ACCOUNT,
	 DECODE ( I_CC_EXCHANGE,
	 'TQD',
	 'ED2',
	 I_CC_EXCHANGE ) as V_CC_EXCHANGE,
	 V_CC_EXCHANGE as CC_EXCHANGE,
	 CC_CASH_COLLATERAL_AMOUNT as CC_CASH_COLLATERAL_AMOUNT,
	 dsf_1.DF_NAME as v_WATERFALL_LKP,
	 SUBSTRING ( v_WATERFALL_LKP,
	 1,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) -1 ) as v_WATERFALL_NM,
	 SUBSTRING ( v_WATERFALL_LKP,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) + 1 ) as v_WATERFALL_SRVC,
	 v_WATERFALL_NM as CC_DEFAULT_FUND,
	 v_WATERFALL_SRVC as CC_WATERFALL_SRVC,
	 CC_ENTITY_ID as CC_ENTITY_ID,
	 'Cash' as CC_COLLATERAL_GROUP,
	 1 as ERROR_IND,
	 dsf_2.HOUSE_CLIENT_FLAG as v_HOUSE_CLIENT_FLAG,
	 ( CASE WHEN IN ( SUBSTRING ( CC_SUB_ACCOUNT,
	 1,
	 1 ),
	 'S',
	 'O',
	 'V',
	 'F',
	 'R' ) THEN CC_SUB_ACCOUNT ELSE v_HOUSE_CLIENT_FLAG END ) as v_SUB_ACCOUNT_CHK,
	 CC_MNEMONIC || '_' || v_SUB_ACCOUNT_CHK as v_CC_SUB_ACC,
	 v_SUB_ACCOUNT_CHK as o_SUB_ACCOUNT,
	 v_CC_SUB_ACC as CollateralAccountID,
	 DECODE ( CC_COLLATERAL_GROUP,
	 'ATS',
	 dsf_3.STRING_VALUE2,
	 'ITS',
	 dsf_4.STRING_VALUE2,
	 'XXX',
	 dsf_6.STRING_VALUE2,
	 'YYY',
	 dsf_5.STRING_VALUE2,
	 'Cash' ) as v_AssetType,
	 v_AssetType as AssetType,
	 dsf_7.CURRENCY_MNEMONIC as v_Ccy,
	 v_Ccy as o_Ccy,
	 ( CASE WHEN v_AssetType = 'Cash' THEN CC_CASH_COLLATERAL_AMOUNT ELSE NULL END ) as Cash_Value,
	 ( CASE WHEN v_AssetType = 'Cash' THEN v_Ccy ELSE null END ) as Cash_Value_Ccy,
	 ( CASE WHEN v_AssetType = 'Cash' THEN CC_CASH_COLLATERAL_AMOUNT ELSE NULL END ) as ValuePostHaircut,
	 ( CASE WHEN v_AssetType = 'Cash' THEN v_Ccy ELSE null END ) as ValuePostHaircut_Ccy,
	 ( CASE WHEN IN ( CC_SUB_ACCOUNT,
	 'F',
	 'R' ) THEN 'DFLT' ELSE 'MGIN' END ) as CollateralRequirement,
	 SUBSTRING ( TO_DATE ( TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ),
	 'YYYY-MM-DD' ),
	 'YYYY-MM-DD' ),
	 1,
	 10 ) || 'T' || SUBSTRING ( TO_TIMESTAMP ( TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ),
	 'HH24MISS' ),
	 'HH24MISS' ),
	 12 ) as v_Date,
	 TO_VARCHAR ( TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ),
	 'YYYY-MM-DD' ) as v_AS_OF_DATE,
	 :LKP.SC_LKP_APPLICATION_VARIABLES_BOE ( PMSessionName,
	 'BOE_STATIC_VAL' ) as v_APP_REP_ID,
	 :LKP.SC_LKP_FILE_GENERATED_DETAILS_DIM_VERSION ( '{{ var("BATCH_ID") }}',
	 v_APP_REP_ID ) as v_Version,
	 ( CASE WHEN v_Version IS NULL THEN 1 ELSE ( TO_NUMBER ( v_Version ) + 1 ) END ) as v_initial_value_handle,
	 '{{ var("CCP_CODE") }}' || '_' || v_AS_OF_DATE || '_' || 'CCPCollRpt_' || v_Date || '_V' || v_initial_value_handle || '.XML' as v_FILENAME,
	 v_FILENAME as FILENAME,
	 1 as ENABLE_IND,
	 dsf_10.ID as FILE_GEN_DETAILS_ID,
	 CASH_COLLATERAL_POST_HAIRCUT as CASH_COLLATERAL_POST_HAIRCUT,
	 dsf_11.ACTIVE_Y_N as FX_HAIRCUT_SWITCH
From DSR_EXP_CASH_COLOut as DSR_EXP_CASH_COLOut
LEFT JOIN (
SELECT DF_NAME, ID FROM (   SELECT DF_NAME, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT DF_NAME, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY ID NULLS LAST) AS rnk_fst     FROM ( SELECT        EXCHANGE_DIM.ID as ID,        EXCHANGE_DIM.DEFAULT_FUND || '~' || EXCHANGE_DIM.NAME as DF_NAME  FROM        EXCHANGE_DIM  WHERE       TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') >= EFFECTIVE_DATE AND      TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') <= NVL(EXPIRATION_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.ID = CC_EXCHANGE_ID
LEFT JOIN (
SELECT HOUSE_CLIENT_FLAG, SUB_ACCOUNT FROM (   SELECT HOUSE_CLIENT_FLAG, SUB_ACCOUNT,   ROW_NUMBER() OVER (PARTITION BY SUB_ACCOUNT ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT HOUSE_CLIENT_FLAG, SUB_ACCOUNT,   ROW_NUMBER() OVER (PARTITION BY SUB_ACCOUNT ORDER BY SUB_ACCOUNT NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        VW_ML_CALYP_SUB_ACCOUNT )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
