	 EXP_CASH_COLOut2.ENABLE_IND as CollateralRequirementType1Code_T1_I_ENABLE_IND,
	 EXP_CASH_COLOut2.ENABLE_IND as COL_RPT_VAL_EN_IND,
	 EXP_CASH_COLOut2.ENABLE_IND as ActiveCurrencyCode_T7_I_ENABLE_IND
From EXP_CASH_COLOut as EXP_CASH_COLOut),

