EXP_BNK_DSRO_SECOut as (
	/* transType: "Expression" */
Select 
	ID as ID,
	 BUSINESS_DATE as BUSINESS_DATE,
	 MNEMONIC as MNEMONIC,
	 SUB_ACCOUNT as SUB_ACCOUNT,
	 SECURITY_CURRENCY_ID as SECURITY_CURRENCY_ID,
	 SECURITY_PRODUCT_CODE as SECURITY_PRODUCT_CODE,
	 MARKET_VALUE as MARKET_VALUE,
	 ENTITY_ID as ENTITY_ID,
	 MARKET_VALUE_POST_HAIRCUT as MARKET_VALUE_POST_HAIRCUT,
	 EXCHANGE as EXCHANGE,
	 dsf_1.DF_NAME as v_WATERFALL_LKP,
	 SUBSTRING ( v_WATERFALL_LKP,
	 1,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) -1 ) as v_WATERFALL_NM,
	 SUBSTRING ( v_WATERFALL_LKP,
	 REGEXP_INSTR ( v_WATERFALL_LKP,
	 '~' ) + 1 ) as v_WATERFALL_SRVC,
	 v_WATERFALL_NM as DSRO_WATERFALL_NM,
	 v_WATERFALL_SRVC as DSRO_WATERFALL_SRVC,
	 1 as ENABLE_IND,
	 dsf_2.CURRENCY_MNEMONIC as v_Ccy,
	 v_Ccy as o_Ccy,
	 dsf_3.HOUSE_CLIENT_FLAG as v_HOUSE_CLIENT_FLAG,
	 ( CASE WHEN IN ( SUBSTRING ( SUB_ACCOUNT,
	 1,
	 1 ),
	 'S',
	 'O',
	 'V',
	 'F',
	 'R' ) THEN SUB_ACCOUNT ELSE v_HOUSE_CLIENT_FLAG END ) as v_SUB_ACCOUNT_CHK,
	 MNEMONIC || '_' || v_SUB_ACCOUNT_CHK as v_DSRO_SUB_ACC,
	 v_SUB_ACCOUNT_CHK as o_SUB_ACCOUNT,
	 v_DSRO_SUB_ACC as DSRO_CollateralAccountID,
	 ( CASE WHEN IN ( SUB_ACCOUNT,
	 'F',
	 'R' ) THEN 'DFLT' ELSE 'MGIN' END ) as DSRO_CollateralRequirement,
	 ( CASE WHEN SECURITY_TYPE = 'Triparty Collateral' THEN 'TripartyRepo' ELSE 'Security' END ) as v_AssetType,
	 v_AssetType as AssetType,
	 ( CASE WHEN v_AssetType = 'TripartyRepo' THEN MARKET_VALUE ELSE NULL END ) as TripartyRepo_Value,
	 ( CASE WHEN v_AssetType = 'TripartyRepo' THEN v_Ccy ELSE NULL END ) as TripartyRepo_Value_Ccy,
	 ( CASE WHEN v_AssetType = 'Security' THEN SECURITY_PRODUCT_CODE ELSE NULL END ) as SecurityIdentifier,
	 ( CASE WHEN v_AssetType = 'Security' THEN MARKET_VALUE ELSE NULL END ) as v_MarketValue,
	 v_MarketValue as MarketValue,
	 ( CASE WHEN v_AssetType = 'Security' THEN v_Ccy ELSE NULL END ) as MarketValue_Ccy,
	 ( CASE WHEN IN ( v_AssetType,
	 'Security',
	 'TripartyRepo' ) THEN MARKET_VALUE_POST_HAIRCUT ELSE NULL END ) as v_ValuePostHairCut,
	 v_ValuePostHairCut as ValuePostHairCut,
	 ( CASE WHEN IN ( v_AssetType,
	 'Security',
	 'TripartyRepo' ) THEN v_Ccy ELSE null END ) as ValuePostHairCut_Ccy,
	 SUBSTRING ( TO_DATE ( TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ),
	 'YYYY-MM-DD' ),
	 'YYYY-MM-DD' ),
	 1,
	 10 ) || 'T' || SUBSTRING ( TO_TIMESTAMP ( TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ),
	 'HH24MISS' ),
	 'HH24MISS' ),
	 12 ) as v_Date,
	 TO_VARCHAR ( TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ),
	 'YYYY-MM-DD' ) as v_AS_OF_DATE,
	 :LKP.SC_LKP_APPLICATION_VARIABLES_BOE ( PMSessionName,
	 'BOE_STATIC_VAL' ) as v_APP_REP_ID,
	 :LKP.SC_LKP_FILE_GENERATED_DETAILS_DIM_VERSION ( '{{ var("BATCH_ID") }}',
	 v_APP_REP_ID ) as v_Version,
	 ( CASE WHEN v_Version IS NULL THEN 1 ELSE ( TO_NUMBER ( v_Version ) + 1 ) END ) as v_initial_value_handle,
	 '{{ var("CCP_CODE") }}' || '_' || v_AS_OF_DATE || '_' || 'CCPCollRpt_' || v_Date || '_V' || v_initial_value_handle || '.XML' as v_FILENAME,
	 v_FILENAME as FILENAME,
	 dsf_6.ID as FILE_GEN_DETAILS_ID,
	 BOE_SECURITY_TYPE_NAME as BOE_SECURITY_TYPE_NAME,
	 BOE_SECURITY_TYPE as BOE_SECURITY_TYPE,
	 ( CASE WHEN SECURITY_TYPE  !=  'Triparty Collateral' THEN 1 ELSE 0 END ) as BOE_SEC_TYPE_EI
From DSR_EXP_BNK_DSRO_SECOut as DSR_EXP_BNK_DSRO_SECOut
LEFT JOIN (
SELECT DF_NAME, ID FROM (   SELECT DF_NAME, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT DF_NAME, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY ID NULLS LAST) AS rnk_fst     FROM ( SELECT        EXCHANGE_DIM.ID as ID,        EXCHANGE_DIM.DEFAULT_FUND || '~' || EXCHANGE_DIM.NAME as DF_NAME  FROM        EXCHANGE_DIM  WHERE       TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') >= EFFECTIVE_DATE AND      TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') <= NVL(EXPIRATION_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.ID = i_EXCHANGE_ID
LEFT JOIN (
SELECT CURRENCY_MNEMONIC, ID FROM (   SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY ID NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        CURRENCY_DIM )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.ID = SECURITY_CURRENCY_ID
LEFT JOIN (
SELECT HOUSE_CLIENT_FLAG, SUB_ACCOUNT FROM (   SELECT HOUSE_CLIENT_FLAG, SUB_ACCOUNT,   ROW_NUMBER() OVER (PARTITION BY SUB_ACCOUNT ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT HOUSE_CLIENT_FLAG, SUB_ACCOUNT,   ROW_NUMBER() OVER (PARTITION BY SUB_ACCOUNT ORDER BY SUB_ACCOUNT NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        VW_ML_CALYP_SUB_ACCOUNT )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.SUB_ACCOUNT = SUB_ACCOUNT
LEFT JOIN (
SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME FROM (   SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY STRING_VALUE, VARIABLE_NAME NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        APPLICATION_VARIABLES )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_4
ON dsf_4.STRING_VALUE = '{{ var("PMSessionName") }}' AND dsf_4.VARIABLE_NAME = 'BOE_STATIC_VAL'
LEFT JOIN (
SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID FROM (   SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY BATCH_ID, APPLICATION_REPORT_ID NULLS LAST) AS rnk_fst     FROM ( SELECT        MAX(NVL(FILE_GENERATED_DETAILS_DIM.VERSION_NO,0)) as VERSION_NO,        FILE_GENERATED_DETAILS_DIM.BATCH_ID as BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID  FROM        FILE_GENERATED_DETAILS_DIM  INNER JOIN      BATCH_MASTER   ON    FILE_GENERATED_DETAILS_DIM.BATCH_ID= BATCH_MASTER.BATCH_ID AND     FILE_GENERATED_DETAILS_DIM.STATUS= 'C' AND     FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID= '{{ var("REPORT_ID") }}' AND     FILE_GENERATED_DETAILS_DIM.BATCH_ID= '{{ var("BATCH_ID") }}'  GROUP BY        FILE_GENERATED_DETAILS_DIM.BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_5
ON dsf_5.BATCH_ID = '{{ var("BATCH_ID") }}' AND dsf_5.APPLICATION_REPORT_ID = v_APP_REP_ID
LEFT JOIN (
SELECT ID, BATCH_ID, APPLICATION_REPORT_ID FROM (   SELECT ID, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT ID, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY BATCH_ID, APPLICATION_REPORT_ID NULLS LAST) AS rnk_fst     FROM ( SELECT        FILE_GENERATED_DETAILS_DIM.ID as ID,        FILE_GENERATED_DETAILS_DIM.BATCH_ID as BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID  FROM        FILE_GENERATED_DETAILS_DIM  INNER JOIN      BATCH_MASTER   ON    FILE_GENERATED_DETAILS_DIM.BATCH_ID= BATCH_MASTER.BATCH_ID AND     FILE_GENERATED_DETAILS_DIM.BATCH_ID= '{{ var("BATCH_ID") }}' AND     FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID= '{{ var("REPORT_ID") }}' AND     DATE_TRUNC('DAY',FILE_GENERATED_DETAILS_DIM.FILE_GEN_START_DATETIME)= DATE_TRUNC('DAY',TO_DATE('{{ var("BATCH_START_DATE") }}','DD-MON-YYYY'))  ORDER BY        TRUNC ( FILE_GEN_START_DATETIME ) DESC )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_6
ON dsf_6.BATCH_ID = '{{ var("BATCH_ID") }}' AND dsf_6.APPLICATION_REPORT_ID = '{{ var("REPORT_ID") }}'
),

