LEFT JOIN (
SELECT RESIGNATION_DATE, MRG_MNEMONIC FROM (  SELECT RESIGNATION_DATE, MRG_MNEMONIC,  ROW_NUMBER() OVER (PARTITION BY MRG_MNEMONIC ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT RESIGNATION_DATE, MRG_MNEMONIC,  ROW_NUMBER() OVER (PARTITION BY MRG_MNEMONIC ORDER BY MRG_MNEMONIC NULLS LAST) AS rnk_fst   FROM ( SELECT distinct    VW_RDR_MEMBER_DTLS.RESIGNATION_DATE as RESIGNATION_DATE,    VW_RDR_MEMBER_DTLS.MRG_MNEMONIC as MRG_MNEMONIC FROM    VW_RDR_MEMBER_DTLS ORDER BY    VW_RDR_MEMBER_DTLS.MRG_MNEMONIC,    NVL ( VW_RDR_MEMBER_DTLS.RESIGNATION_DATE,TO_DATE ( '31-DEC-2099','DD-MON-YYYY' ) ) - - )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.MRG_MNEMONIC = SUBSTR(CollateralAccountID
),

