	 ValuePostHaircut as ValuePostHaircut,
	 ValuePostHaircut_Ccy as ValuePostHaircut_Ccy,
	 BoE_Security_Type as BoE_Security_Type,
	 '{{ var("BATCH_ID") }}' as o_BATCH_ID,
	 '{{ var("REPORT_ID") }}' as o_REPORT_ID,
	 TO_DATE ( LTRIM ( RTRIM ( '{{ var("BATCH_BUSINESS_DATE") }}' ) ),
	 'YYYYMMDD' ) as o_BATCH_BUSINESS_DATE,
	 :LKP.SC_LKP_APPLICATION_VARIABLES_BOE ( PMSessionName,
	 'BOE_STATIC_VAL' ) as v_APP_REP_ID,
	 :LKP.SC_LKP_FILE_GENERATED_DETAILS_DIM_VERSION ( '{{ var("BATCH_ID") }}',
	 v_APP_REP_ID ) as v_Version,
	 ( CASE WHEN v_Version IS NULL THEN 1 ELSE ( TO_NUMBER ( v_Version ) + 1 ) END ) as o_Initial_value_handle
From DSR_EXP_INTERIM_coll_rptOut as DSR_EXP_INTERIM_coll_rptOut
LEFT JOIN (
SELECT CURRENCY_MNEMONIC, ID FROM (   SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY ID NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        CURRENCY_DIM )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.ID = COLLATERAL_CURRENCY_ID
LEFT JOIN (
SELECT STRING_VALUE2, STRING_VALUE FROM (   SELECT STRING_VALUE2, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT STRING_VALUE2, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst     FROM ( SELECT        APPLICATION_VARIABLES.STRING_VALUE2 as STRING_VALUE2,        APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE  FROM        APPLICATION_VARIABLES  WHERE     VARIABLE_NAME= 'BOE_STATIC_VAL' )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.STRING_VALUE = 'AccountIDScheme_Coll'
LEFT JOIN (
SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME FROM (   SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY STRING_VALUE, VARIABLE_NAME NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        APPLICATION_VARIABLES )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.STRING_VALUE = '{{ var("PMSessionName") }}' AND dsf_3.VARIABLE_NAME = 'BOE_STATIC_VAL'
LEFT JOIN (
SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID FROM (   SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY BATCH_ID, APPLICATION_REPORT_ID NULLS LAST) AS rnk_fst     FROM ( SELECT        MAX(NVL(FILE_GENERATED_DETAILS_DIM.VERSION_NO,0)) as VERSION_NO,        FILE_GENERATED_DETAILS_DIM.BATCH_ID as BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID  FROM        FILE_GENERATED_DETAILS_DIM  INNER JOIN      BATCH_MASTER   ON    FILE_GENERATED_DETAILS_DIM.BATCH_ID= BATCH_MASTER.BATCH_ID AND     FILE_GENERATED_DETAILS_DIM.STATUS= 'C' AND     FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID= '{{ var("REPORT_ID") }}' AND     FILE_GENERATED_DETAILS_DIM.BATCH_ID= '{{ var("BATCH_ID") }}'  GROUP BY        FILE_GENERATED_DETAILS_DIM.BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_4
ON dsf_4.BATCH_ID = '{{ var("BATCH_ID") }}' AND dsf_4.APPLICATION_REPORT_ID = v_APP_REP_ID
),

EXP_INTERIM_coll_rptOut2 as (
	/* transType: "Expression" */
Select 
	TABLE_NAME as TABLE_NAME,
	 MNEMONIC as MNEMONIC,
	 COLLATERAL_CURRENCY_ID as COLLATERAL_CURRENCY_ID,
	 ( CASE WHEN TABLE_NAME = 'RR_BNK_CASH_COLLATERAL_FACT' OR TABLE_NAME = 'RR_BNK_LIABILITY_COVER_FACT' THEN dsf_1.CURRENCY_MNEMONIC ELSE null END ) as COLLATERAL_CURRENCY_ID_CASH,
	 ( CASE WHEN TABLE_NAME = 'RR_BNK_DSRO_SEC_BALANCES_FACT' THEN dsf_1.CURRENCY_MNEMONIC ELSE null END ) as COLLATERAL_CURRENCY_ID2_DSRO,
	 SUB_ACCOUNT as SUB_ACCOUNT,
	 EXCHANGE as EXCHANGE,
	 PREHAIRCUT_VALUE as PREHAIRCUT_VALUE,
	 POSTHAIRCUT_VALUE as POSTHAIRCUT_VALUE,
	 DEFAULT_FUND as DEFAULT_FUND,
	 ENTITY_ID as ENTITY_ID,
	 COLLATERAL_GROUP as COLLATERAL_GROUP,
	 ISIN as ISIN,
	 Sender_LEI as Sender_LEI,
	 Sender_Scheme_Name as Sender_Scheme_Name,
	 Receiver_LEI as Receiver_LEI,
	 Receiver_Scheme_Name as Receiver_Scheme_Name,
	 DECODE ( '{{ var("PMRepositoryServiceName") }}',
	 'LCH_REP_SVC_PROD',
	 'BOE_CCP_PROD',
	 'BOE_CCP_TEST' ) as Business_Service,
	 Msg_Def_Id as Msg_Def_Id,
	 TO_VARCHAR ( DATE_TRUNC ( 'DAY',
	 dsCurrentTimestamp ( ) ),
	 'YYYY-MM-DD' ) || 'T' || TO_VARCHAR ( dsCurrentTimestamp ( ),
	 'HH24:Mi:SS' ) || 'Z' as Creation_Date,
	 TO_VARCHAR ( TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ),
	 'YYYY-MM-DD' ) || 'T00:00:00Z' as From_Date_Time,
	 TO_VARCHAR ( TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ),
	 'YYYY-MM-DD' ) || 'T00:00:00Z' as To_Date_Time,
	 Waterfall_Name as Waterfall_Name,
	 Waterfall_Service as Waterfall_Service,
	 CollateralAccountID as CollateralAccountID,
	 dsf_2.STRING_VALUE2 as o_CollateralAccountIDType,
	 AssetType as AssetType,
	 Cash_Value as Cash_Value,
	 Cash_Value_Ccy as Cash_Value_Ccy,
	 CollateralRequirement as CollateralRequirement,
	 FILENAME as FILENAME,
	 TripartyRepo_Value as TripartyRepo_Value,
	 TripartyRepo_Value_Ccy as TripartyRepo_Value_Ccy,
	 SecurityIdentifier as SecurityIdentifier,
	 MarketValue as MarketValue,
	 MarketValue_Ccy as MarketValue_Ccy,
	 ValuePostHaircut as ValuePostHaircut,
	 ValuePostHaircut_Ccy as ValuePostHaircut_Ccy,
	 BoE_Security_Type as BoE_Security_Type,
	 '{{ var("BATCH_ID") }}' as o_BATCH_ID,
	 '{{ var("REPORT_ID") }}' as o_REPORT_ID,
	 TO_DATE ( LTRIM ( RTRIM ( '{{ var("BATCH_BUSINESS_DATE") }}' ) ),
	 'YYYYMMDD' ) as o_BATCH_BUSINESS_DATE,
	 :LKP.SC_LKP_APPLICATION_VARIABLES_BOE ( PMSessionName,
	 'BOE_STATIC_VAL' ) as v_APP_REP_ID,
	 :LKP.SC_LKP_FILE_GENERATED_DETAILS_DIM_VERSION ( '{{ var("BATCH_ID") }}',
	 v_APP_REP_ID ) as v_Version,
	 ( CASE WHEN v_Version IS NULL THEN 1 ELSE ( TO_NUMBER ( v_Version ) + 1 ) END ) as o_Initial_value_handle
From DSR_EXP_INTERIM_coll_rptOut as DSR_EXP_INTERIM_coll_rptOut
LEFT JOIN (
SELECT CURRENCY_MNEMONIC, ID FROM (   SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT CURRENCY_MNEMONIC, ID,   ROW_NUMBER() OVER (PARTITION BY ID ORDER BY ID NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        CURRENCY_DIM )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.ID = COLLATERAL_CURRENCY_ID
LEFT JOIN (
SELECT STRING_VALUE2, STRING_VALUE FROM (   SELECT STRING_VALUE2, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT STRING_VALUE2, STRING_VALUE,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst     FROM ( SELECT        APPLICATION_VARIABLES.STRING_VALUE2 as STRING_VALUE2,        APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE  FROM        APPLICATION_VARIABLES  WHERE     VARIABLE_NAME= 'BOE_STATIC_VAL' )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.STRING_VALUE = 'AccountIDScheme_Coll'
LEFT JOIN (
SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME FROM (   SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT STRING_VALUE3, STRING_VALUE, VARIABLE_NAME,   ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, VARIABLE_NAME ORDER BY STRING_VALUE, VARIABLE_NAME NULLS LAST) AS rnk_fst     FROM ( SELECT        *  FROM        APPLICATION_VARIABLES )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.STRING_VALUE = '{{ var("PMSessionName") }}' AND dsf_3.VARIABLE_NAME = 'BOE_STATIC_VAL'
LEFT JOIN (
SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID FROM (   SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT VERSION_NO, BATCH_ID, APPLICATION_REPORT_ID,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, APPLICATION_REPORT_ID ORDER BY BATCH_ID, APPLICATION_REPORT_ID NULLS LAST) AS rnk_fst     FROM ( SELECT        MAX(NVL(FILE_GENERATED_DETAILS_DIM.VERSION_NO,0)) as VERSION_NO,        FILE_GENERATED_DETAILS_DIM.BATCH_ID as BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID  FROM        FILE_GENERATED_DETAILS_DIM  INNER JOIN      BATCH_MASTER   ON    FILE_GENERATED_DETAILS_DIM.BATCH_ID= BATCH_MASTER.BATCH_ID AND     FILE_GENERATED_DETAILS_DIM.STATUS= 'C' AND     FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID= '{{ var("REPORT_ID") }}' AND     FILE_GENERATED_DETAILS_DIM.BATCH_ID= '{{ var("BATCH_ID") }}'  GROUP BY        FILE_GENERATED_DETAILS_DIM.BATCH_ID,        FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_4
ON dsf_4.BATCH_ID = '{{ var("BATCH_ID") }}' AND dsf_4.APPLICATION_REPORT_ID = v_APP_REP_ID
),

LKP_BATCH_MASTEROut as (
	/* transType: "Lookup Procedure" */
Select 
	BATCH_ID as BATCH_ID,
	 BATCH_FEED_INFO as BATCH_FEED_INFO,
	 REMARKS as REMARKS,
	 AUTO_REPORT_SUBMISSION_FLG as AUTO_REPORT_SUBMISSION_FLG,
	 EXP_INTERIM_coll_rptOut.BATCH_ID1 as BATCH_ID1_1,
	 EXP_INTERIM_coll_rpt.o_BATCH_ID AS BATCH_ID1_2 
FROM
	EXP_INTERIM_coll_rptOut1 as EXP_INTERIM_coll_rptOut1 
 LEFT JOIN BATCH_MASTEROut
ON
	BATCH_ID = BATCH_ID1
 
),

LKP_FILE_GENEREATED_DETAILS_DIM_CHKOut as (
	/* transType: "Lookup Procedure" */
Select 
	ID as ID,
	 FILE_NAME as FILE_NAME,
	 BATCH_ID as BATCH_ID,
	 DESCRIPTION as DESCRIPTION,
	 APPLICATION_REPORT_ID as APPLICATION_REPORT_ID,
	 APPLICATION_ID as APPLICATION_ID,
	 APPLICATION_NAME as APPLICATION_NAME,
	 CREATION_DATETIME as CREATION_DATETIME,
	 SENDER as SENDER,
	 RECIPIENT as RECIPIENT,
	 FILE_GEN_START_DATETIME as FILE_GEN_START_DATETIME,
	 FILE_GEN_END_DATETIME as FILE_GEN_END_DATETIME,
	 TOTAL_RECORDS as TOTAL_RECORDS,
	 STATUS as STATUS,
	 COMMENTS as COMMENTS,
	 EXP_INTERIM_coll_rpt.o_BATCH_ID AS i_BATCH_ID,
	 EXP_INTERIM_coll_rpt.o_REPORT_ID AS i_APPLICATION_REPORT_ID 
FROM
	EXP_INTERIM_coll_rptOut2 as EXP_INTERIM_coll_rptOut2 
 LEFT JOIN  ( select * from (
select 
*,BATCH_ID,APPLICATION_REPORT_ID,row_number() over(partition by BATCH_ID,APPLICATION_REPORT_ID order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,BATCH_ID,APPLICATION_REPORT_ID,row_number() over(partition by BATCH_ID,APPLICATION_REPORT_ID order by BATCH_ID,APPLICATION_REPORT_ID nulls last) as rnk_fst
from ( SELECT
       FILE_GENERATED_DETAILS_DIM.ID as ID,
       FILE_GENERATED_DETAILS_DIM.FILE_NAME as FILE_NAME,
       FILE_GENERATED_DETAILS_DIM.DESCRIPTION as DESCRIPTION,
       FILE_GENERATED_DETAILS_DIM.APPLICATION_ID as APPLICATION_ID,
       FILE_GENERATED_DETAILS_DIM.APPLICATION_NAME as APPLICATION_NAME,
       FILE_GENERATED_DETAILS_DIM.CREATION_DATETIME as CREATION_DATETIME,
       FILE_GENERATED_DETAILS_DIM.SENDER as SENDER,
       FILE_GENERATED_DETAILS_DIM.RECIPIENT as RECIPIENT,
       FILE_GENERATED_DETAILS_DIM.FILE_GEN_START_DATETIME as FILE_GEN_START_DATETIME,
       FILE_GENERATED_DETAILS_DIM.FILE_GEN_END_DATETIME as FILE_GEN_END_DATETIME,
       FILE_GENERATED_DETAILS_DIM.TOTAL_RECORDS as TOTAL_RECORDS,
       FILE_GENERATED_DETAILS_DIM.STATUS as STATUS,
       FILE_GENERATED_DETAILS_DIM.COMMENTS as COMMENTS,
       FILE_GENERATED_DETAILS_DIM.BATCH_ID as BATCH_ID,
       FILE_GENERATED_DETAILS_DIM.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID
 FROM
       FILE_GENERATED_DETAILS_DIM
 WHERE   
   FILE_GENERATED_DETAILS_DIM.STATUS= 'I' AND  
   FILE_GENERATED_DETAILS_DIM.BATCH_ID= '{{ var("BATCH_ID") }}' )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	BATCH_ID = i_BATCH_ID
	AND APPLICATION_REPORT_ID = i_APPLICATION_REPORT_ID
 
),

EXP_INTERIM_coll_rpt_master as (
  Select
  	EXP_INTERIM_coll_rptOut.FILENAME as FILENAME,
	 EXP_INTERIM_coll_rptOut.o_Initial_value_handle as o_Version,
	 EXP_INTERIM_coll_rptOut.o_BATCH_BUSINESS_DATE as o_BATCH_BUSINESS_DATE
  From EXP_INTERIM_coll_rptOut as EXP_INTERIM_coll_rptOut
),
dsJoiner_AGG_DISTINCT_FILENM0Out as (
	/* transType: "Joiner" */
Select 
	LKP_FILE_GENEREATED_DETAILS_DIM_CHKOut.ID as ID,
	 LKP_FILE_GENEREATED_DETAILS_DIM_CHKOut.BATCH_ID as BATCH_ID,
	 LKP_FILE_GENEREATED_DETAILS_DIM_CHKOut.APPLICATION_REPORT_ID as APPLICATION_REPORT_ID,
	 EXP_INTERIM_coll_rpt_master.FILENAME as FILENAME,
	 EXP_INTERIM_coll_rpt_master.o_Version as o_Version,
	 EXP_INTERIM_coll_rpt_master.o_BATCH_BUSINESS_DATE as o_BATCH_BUSINESS_DATE,
	 LKP_BATCH_MASTEROut.BATCH_FEED_INFO as BATCH_FEED_INFO,
	 LKP_BATCH_MASTEROut.REMARKS as REMARKS,
	 LKP_BATCH_MASTEROut.AUTO_REPORT_SUBMISSION_FLG as AUTO_REPORT_SUBMISSION_FLG,
	 ROW_NUMBER ( ) OVER ( ORDER BY 1 ) as jkey 
From
EXP_INTERIM_coll_rpt_master as EXP_INTERIM_coll_rpt_master INNER JOIN LKP_FILE_GENEREATED_DETAILS_DIM_CHKOut as LKP_FILE_GENEREATED_DETAILS_DIM_CHKOut 
ON
EXP_INTERIM_coll_rpt_master.jkey = LKP_FILE_GENEREATED_DETAILS_DIM_CHKOut.jkey
 INNER JOIN LKP_BATCH_MASTEROut as LKP_BATCH_MASTEROut 
ON
EXP_INTERIM_coll_rpt_master.jkey = LKP_BATCH_MASTEROut.jkey
 
),

AGG_DISTINCT_FILENM_Out as (
	/* transType: "Aggregator" */
 
 select 
	ID as ID,
	 BATCH_ID as BATCH_ID,
	 APPLICATION_REPORT_ID as APPLICATION_REPORT_ID,
	 FILENAME as FILENAME,
	 o_Version as o_Version
 from dsJoiner_AGG_DISTINCT_FILENM0Out
 group by ID, BATCH_ID, APPLICATION_REPORT_ID, FILENAME, o_Version
),
AGG_DISTINCT_FILENM_NonGroupBy as (
 select 
  	ID,
	 BATCH_ID,
	 APPLICATION_REPORT_ID,
	 FILENAME,
	 o_Version,
	 o_BATCH_BUSINESS_DATE,
	 BATCH_FEED_INFO,
	 REMARKS,
	 AUTO_REPORT_SUBMISSION_FLG
 from (
  select 
   	ID,
	 BATCH_ID,
	 APPLICATION_REPORT_ID,
	 FILENAME,
	 o_Version,
	 o_BATCH_BUSINESS_DATE,
	 BATCH_FEED_INFO,
	 REMARKS,
	 AUTO_REPORT_SUBMISSION_FLG,
   ROW_NUMBER() OVER (
    PARTITION BY ID, BATCH_ID, APPLICATION_REPORT_ID, FILENAME, o_Version
    ORDER BY ID, BATCH_ID, APPLICATION_REPORT_ID, FILENAME, o_Version
   ) as rnk_lst
  from dsJoiner_AGG_DISTINCT_FILENM0Out
 ) t
 where rnk_lst = 1
),
AGG_DISTINCT_FILENMOut as (
 select 
	dsf_1.ID,
	 dsf_1.BATCH_ID,
	 dsf_1.APPLICATION_REPORT_ID,
	 dsf_1.FILENAME,
	 dsf_1.o_Version,
	 dsf_2.o_BATCH_BUSINESS_DATE,
	 dsf_2.BATCH_FEED_INFO,
	 dsf_2.REMARKS,
	 dsf_2.AUTO_REPORT_SUBMISSION_FLG
 from AGG_DISTINCT_FILENM_Out dsf_1
 inner join AGG_DISTINCT_FILENM_NonGroupBy dsf_2 on dsf_1.ID = dsf_2.ID AND dsf_1.BATCH_ID = dsf_2.BATCH_ID AND dsf_1.APPLICATION_REPORT_ID = dsf_2.APPLICATION_REPORT_ID AND dsf_1.FILENAME = dsf_2.FILENAME AND dsf_1.o_Version = dsf_2.o_Version
)
),

EXP_UPD_FILE_GEN_DIMOut as (
	/* transType: "Expression" */
Select 
	ID as ID,
	 BATCH_ID as BATCH_ID,
	 APPLICATION_REPORT_ID as APPLICATION_REPORT_ID,
	 FILENAME as FILENAME,
	 o_Version as o_Version,
	 o_BATCH_BUSINESS_DATE as o_BATCH_BUSINESS_DATE,
	 BATCH_FEED_INFO as BATCH_FEED_INFO,
	 REMARKS as REMARKS,
	 AUTO_REPORT_SUBMISSION_FLG as AUTO_REPORT_SUBMISSION_FLG,
	 ( CASE WHEN AUTO_REPORT_SUBMISSION_FLG = 'Y' THEN REMARKS ELSE NULL END ) as COMMENTS
From AGG_DISTINCT_FILENMOut as AGG_DISTINCT_FILENMOut)

Select 
	ID as ID,
	FILENAME as FILE_NAME,
	BATCH_ID as BATCH_ID,
	APPLICATION_REPORT_ID as APPLICATION_REPORT_ID,
	COMMENTS as COMMENTS,
	o_Version as VERSION_NO 
From EXP_UPD_FILE_GEN_DIMOut as EXP_UPD_FILE_GEN_DIMOut